-- Actionable Strategy steps live once in the canonical Backlog.
-- Existing channel setup tasks are reused; browser setup belongs to AI.
update public.backlog_items set executor='ai', source='strategy:' || lower(project) || ':' || case when title ilike '%LinkedIn%' then 'linkedin' else 'facebook' end
where project in ('devShark','DNESKAi') and (title ilike 'Založit LinkedIn stránku%' or title ilike 'Založit Facebook stránku%' or title ilike 'Facebook stránka DNESKAi založena%');
-- Only owner decisions/answers, personal credentials and identity checks stay JA.
update public.backlog_items set executor='me' where status not in ('done','dropped') and (title ilike '%potvrdit pokračování%' or title ilike '%Klíč%' or title ilike '%API_KEY%' or title ilike '%Otázky z auditu%' or title ilike '%kdo je aktualizuje%');
with steps(project,title,description,executor,source,external_ref) as (values
('devShark','Zapsat výchozí stav IG a Threads','Zapsat počet sledujících, bio, odkazy, typ účtu a datum měření. Oddělit účet od výsledků konkrétních příspěvků; chybějící údaje neuvádět jako nulu.','ai','strategy:devshark:baseline','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Připravit a nastavit vzdělávací bio a odkazy','Připravit jazykově správný příslib, profilovou fotku, odkaz na existující relevantní obsah a UTM pro IG/Threads. Ověřit cílové stránky. Změnu profilu provést v Chrome v dostupné přihlášené relaci.','ai','strategy:devshark:profile','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Kvalifikovat 8–12 aktivních vzdělávacích účtů','Nejdřív znovu použít existující Apify datasety. U každého účtu ověřit jazyk, publikum, poslední aktivitu a vzdělávací zaměření. Vyřadit lifestyle a smíšené vzorky; uložit důvod výběru do Strategie/konkurence.','ai','strategy:devshark:cohort','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Připravit přesný nový plán Apify','Zapsat actor ID, build, vstupy, okno posledních 45 dní, limity výsledků a stop podmínky. Návrh je max. $60 celkem a $2/run. Zkontrolovat ceny, promo expiraci 22.11. a fakturaci 15.11. Neměnit staré rezervace ani schválené hashe.','ai','strategy:devshark:apify-plan','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Schválit konkrétní placený plán Apify','JA: rozhodnout o přesných vstupech a stropu nového plánu. Samotný štítek AI na dalších úkolech neschvaluje placený běh. Schválení zaznamenat k hashi plánu.','me','strategy:devshark:apify-decision','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Zpracovat současné vzorce a otázky publika','Po schválení plánu nejvýš 30 recentních IG příspěvků/účet a 6 Threads účtů × 30 příspěvků. Otázky shrnout anonymně z 12 vybraných postů; ověřit Google Trends a jen 12 relevantních přepisů. Srovnávat stejné stáří/formát; neodvozovat reach z veřejných likes.','ai','strategy:devshark:research','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Převést výzkum do originálních briefů','Z vybraných námětů ve Strategii vytvořit malou sérii do Topics/Design Lab. Každý brief obsahuje konkrétní vzdělávací výsledek, hook, příklad, vizuální směr a měřitelnou hypotézu. Bez moderátora a bez kopírování konkurence.','ai','strategy:devshark:briefs','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Schválit připravené verze pro zveřejnění','JA: zkontrolovat přesné finální verze, nabídky a případné právní nároky. Schválit je standardním workflow před vložením do publikování; obecná strategie ani kategorie AI nenahrazuje schválení obsahu.','me','strategy:devshark:approval','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Propojit schválené verze s Kalendářem','Po schválení propojit každý brief a konkrétní verzi Labu s Kalendářem. Zachovat stávající časy, přepínače, rozpočty a publisher. Zkontrolovat potvrzený receipt, neplést plán s publikací.','ai','strategy:devshark:calendar','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Doplnit nativní Insights 72 h / 7 dní / Stories 24 h','Z Chrome opsat skutečné IG/Threads výsledky k potvrzenému receipt ve Strategii. Feed a Threads měřit kolem 72 h a 7 dní, Stories před expirací kolem 24 h. Zapsat missing jako neznámé, nikoli nulu.','ai','strategy:devshark:insights','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Vyhodnotit srovnatelná pozorování a upravit další briefy','Porovnat hypotézy na stejně starých příspěvcích a dostatečném vzorku. Vyhodnotit sdílení, uložení, návštěvy profilu a skutečné návštěvy výuky, pokud je produkt měří. Výsledky vrátit do Strategie, briefů a plánu; první malé počty nejsou vítěz formátu.','ai','strategy:devshark:review','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Připravit samostatné vzdělávací odpovědi na Threads','Připravit konkrétní odpovědi a doplňující příklady do relevantních diskusí; bez generického spamu. Připravit vlastní Threads verzi hodnotnou i bez Instagramu. Publikování až v rámci schváleného workflow.','ai','strategy:devshark:threads','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Připravit Highlights a nativní Stories interakce','V Chrome ověřit možnost Highlights a skutečných anket/otázek; připravit sady Začni tady / Procvičování / FAQ podle jazyka značky. Nenazývat obrázek interaktivní anketou. Zachovat schvalování publikací.','ai','strategy:devshark:highlights','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Připravit LinkedIn/Facebook adaptace a propojení','Po založení stránek připravit originální jazykové varianty, loga, vzdělávací popisy a ověřené URL; doplnit je do projektu. Ověřit propojení Facebook/Instagram. Automatický publisher pro tyto sítě zatím není zaveden.','ai','strategy:devshark:channels','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Vyřešit případné ověření identity a vlastnictví účtů','JA pouze pokud platforma vyžádá osobní identitu, 2FA nebo rozhodnutí o vlastnictví. Běžné nastavení a klikání patří AI; přístupové údaje neukládat do backlogu.','me','strategy:devshark:identity','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Vyřešit neúspěšnou Threads verzi CSS Grid','Ověřit chybu a stav existujícího receiptu. Opravit příčinu a použít standardní bezpečný recovery; před opakováním ověřit, že příspěvek už nevznikl.','ai','strategy:devshark:publishing','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Ověřit Premium nabídku a technické příklady','Před další publikací ověřit platnost bio s 55% slevou, free-practice cíl, EPSILON a měřítko čísel, reverseWords pro prázdný vstup a přesnost tvrzení o HTTP 403/autentizaci. Opravené verze poslat znovu ke schválení.','ai','strategy:devshark:claims','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Připravit sérii challenge → vysvětlení → procvičení','Začít event loopem, mutací polí a nullish defaulty. Spustit příklady v terminálu/prohlížeči, přidat mechanismus a edge case. Mix 40% predict/explain, 30% debugging, 20% build, 10% interview. Zachovat 16:00 IG/Threads a 19:00 Threads jako baseline.','ai','strategy:devshark:practice-series','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('devShark','Navrhnout Story s řešením a následným vybavením','Otestovat po challenge vysvětlenou odpověď a následný recall úkol. Použít čitelný code/browser capture a stávající zelenou/ink identitu. Připravit nový koncept v Labu bez přepsání schváleného příspěvku.','ai','strategy:devshark:story-answer','https://own-dashboard-tau.vercel.app/projects/devshark?projectTab=strategy'),
('DNESKAi','Zapsat výchozí stav IG a Threads','Zapsat počet sledujících, bio, odkazy, typ účtu a datum měření. Oddělit účet od výsledků konkrétních příspěvků; chybějící údaje neuvádět jako nulu.','ai','strategy:dneskai:baseline','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
('DNESKAi','Připravit a nastavit vzdělávací bio a odkazy','Připravit jazykově správný příslib, profilovou fotku, odkaz na existující relevantní obsah a UTM pro IG/Threads. Ověřit cílové stránky. Změnu profilu provést v Chrome v dostupné přihlášené relaci.','ai','strategy:dneskai:profile','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
('DNESKAi','Kvalifikovat 8–12 aktivních vzdělávacích účtů','Nejdřív znovu použít existující Apify datasety. U každého účtu ověřit jazyk, publikum, poslední aktivitu a vzdělávací zaměření. Vyřadit lifestyle a smíšené vzorky; uložit důvod výběru do Strategie/konkurence.','ai','strategy:dneskai:cohort','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
