('DNESKAi','Vyřešit případné ověření identity a vlastnictví účtů','JA pouze pokud platforma vyžádá osobní identitu, 2FA nebo rozhodnutí o vlastnictví. Běžné nastavení a klikání patří AI; přístupové údaje neukládat do backlogu.','me','strategy:dneskai:identity','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
('DNESKAi','Prověřit OpenAI dots a nejistý GSA receipt na Threads','Ověřit failed OpenAI dots a reconciliovat ambiguous GSA proti nativnímu účtu. Neodesílat GSA znovu, dokud není jasný skutečný stav. Opravu provést standardním guarded workflow.','ai','strategy:dneskai:publishing','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
('DNESKAi','Připravit české praktické náměty a šest sérií','Převést fiktivní poradu na úkoly, zkrátit email a ukázat chybějící hodnoty v tabulce; zvlášť připravit Drive walkthrough oprávnění. Navázat na šest sérií od 16.11. a mix 40% workflow / 30% pojmy / 20% zprávy / 10% otázky.','ai','strategy:dneskai:czech-series','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
('DNESKAi','Zkontrolovat pravidla fotek a carouselů před schválením','Bez Reels a moderátora. Titulek pouze na coveru kromě kódem psaného označení série, žádné zdroje/credits/počty stran veřejně, max. 7 hashtagů. Jediný komentovací keyword přidává kód. Ověřit českou dostupnost, ceny a oprávnění k fotkám interně.','ai','strategy:dneskai:production','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'),
('DNESKAi','Ověřit slíbené keyword materiály a doručení','Před CTA ověřit, že slíbený vzdělávací materiál skutečně existuje a zpráva ho doručí. První odstavec Threads musí nést užitečný důsledek bez hashtagů a topic tagu. Ověřit stories +10 minut a zachovat stávající 08:00/12:30/19:00/21:00 časy.','ai','strategy:dneskai:keyword','https://own-dashboard-tau.vercel.app/projects/dneskai?projectTab=strategy'))
insert into public.backlog_items(user_id,project,title,description,executor,source,external_ref)
select p.user_id,s.project,s.title,s.description,s.executor,s.source,s.external_ref from steps s
join public.projects p on p.slug=case when s.project='devShark' then 'devshark' else 'dneskai' end
where not exists (select 1 from public.backlog_items b where b.user_id=p.user_id and b.source=s.source);
